s?.approvedAt&&<p className="mt-2 text-slate-400">Approved {stamp(job.metrics.approvedAt)}</p>}{job.lastAttempt&&<div className="mt-3 border-t border-slate-700 pt-2"><p className="text-amber-300 mb-1">Latest reprocess cancelled; previous job kept.</p><ErrorCodes values={job.lastAttempt.errorCodes}/></div>}</td><td className="p-3"><div className="flex items-center gap-2 whitespace-nowrap">{job.status!=='Cancelled Job'&&job.metrics?.newStores?.length>0&&<button className={iconButton+' text-amber-300'} disabled={busy} aria-label="Review New Stores" title="Review New Stores" onClick={()=>setStoreReviewJob(job.id)}><Store size={16}/></button>}<button disabled={busy||!!pending} className={iconButton+' text-cyan-300'} aria-label="Reprocess" title="Reprocess" onClick={()=>{setReprocessJob(job);setReprocessPeriod(job.period);}}><RefreshCw size={16} aria-hidden="true"/></button>{['Completed','Completed with Interruption'].includes(job.status)&&<button disabled={busy||!!pending||(job.metrics?.kpi?.flagged&&!job.metrics.kpi.review)} className={iconButton+' text-emerald-300'} aria-label="Approve Job" title={job.metrics?.kpi?.flagged&&!job.metrics.kpi.review?'Review this run in KPI Records before approval':'Approve Job'} onClick={()=>action(job.id,'approve')}><Check size={16} aria-hidden="true"/></button>}{job.status!=='Cancelled Job'&&!pending&&<button disabled={busy} className={iconButton+' text-rose-300'} aria-label="Cancel Job" title="Cancel Job" onClick={()=>action(job.id,'cancel')}><X size={16} aria-hidden="true"/></button>}{pending&&<span role="status" aria-label="Run processing" title="Run processing" className="inline-flex h-8 w-8 items-center justify-center text-cyan-300"><LoaderCircle size={16} className="animate-spin motion-reduce:animate-none" aria-hidden="true"/><span className="sr-only">Run processing</span></span>}</div></td><td className="p-3">{job.status!=='Cancelled Job'&&job.hasAudit&&<button aria-label={`Open audit for ${job.retailer_name} ${job.period}`} title="Open audit logs" className={iconButton} onClick={()=>showAudit(job.id)}><Pencil size={15} aria-hidden="true"/></button>}</td></tr>;})}</tbody></table>{!filtered.length&&<p className="text-sm text-slate-400 text-center p-6">No recorded batch jobs. Start a job with a saved retailer and week.</p>}</div><div className="flex justify-between items-center text-xs"><span>{filtered.length} recorded jobs · 25 rows per page</span><div className="flex gap-3 items-center"><button disabled={page===0} className={button} onClick={()=>setPage(p=>p-1)}>Previous</button><span>{page+1} / {totalPages}</span><button disabled={page>=totalPages-1} className={button} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></section>
