  {audit&&<div className="fixed inset-0 bg-slate-950/85 z-50 flex items-center justify-center p-5"><section role="dialog" aria-modal="true" aria-label="Batch execution audit" className="bg-[var(--panel-background)] border border-slate-600 rounded-xl w-full max-w-6xl max-h-[90vh] flex flex-col"><div className="p-5 border-b border-slate-700 flex justify-between gap-3"><div><h3 className="text-lg font-semibold">Batch Execution Audit</h3><p className="text-xs text-slate-400 mt-1">{audit.job.retailer_name} · {audit.job.period} · {audit.job.status}</p><p className="text-xs text-slate-400 mt-1">Start: {stamp(audit.job.start_time)} · End: {stamp(audit.job.end_time)}</p></div><button aria-label="Close audit" className={button} onClick={()=>setAudit(null)}><X size={16}/></button></div><div className="p-5 overflow-auto"><p className="mb-4 text-sm text-cyan-300">Configuration: {audit.job.metrics?.configurationVersion?`Version ${audit.job.metrics.configurationVersion.version}`:'Not captured for this historical run'}</p><p className="text-xs text-slate-400 mb-3">Input file: {audit.job.metrics?.inputFile?`${audit.job.metrics.inputFile.purpose} · ${audit.job.metrics.inputFile.filename}`:'Legacy defaults'}</p><AuditMetrics metrics={audit.job.metrics}/>{audit.job.metrics?.newStores?.length>0&&<button className={button+' mb-4 text-amber-300'} onClick={()=>{setStoreReviewJob(audit.job.id);setAudit(null);}}>Review New Stores</button>}<table className="w-full text-left text-xs"><thead className="bg-slate-900 text-slate-400"><tr>{['Sequence','Rule / Process','Attempt','Start Time','End Time','Duration','Execution','Error Code','Details'].map(h=><th key={h} className="p-2 whitespace-nowrap">{h}</th>)}</tr></thead><tbody>{audit.entries.map((entry,i)=><tr key={i} className="border-t border-slate-700 align-top"><td className="p-2">{entry.sequence??'—'}</td><td className="p-2">{entry.ruleName}<div className="text-slate-500">{entry.category}</div></td><td className="p-2">{entry.attempt}</td><td className="p-2 whitespace-nowrap">{stamp(entry.startTime)}</td><td className="p-2 whitespace-nowrap">{stamp(entry.endTime)}</td><td className="p-2 whitespace-nowrap">{entry.durationMs} ms</td><td className={`p-2 whitespace-nowrap ${entry.result==='Successful'?'text-emerald-300':'text-rose-300'}`}>{entry.result}</td><td className={`p-2 font-mono ${entry.result==='Successful'?'text-emerald-300':'text-rose-300'}`}>{[entry.executionCode,entry.errorCode].filter(Boolean).join(' · ')}</td><td className="p-2">{entry.message}</td></tr>)}</tbody></table></div></section></div>}
