  if(!selected.length||!window.confirm(`${archived?'Restore':'Archive'} ${selected.length} retailer(s)? Setup, samples and batch history are retained.`))return;
  setBusy(true);setError('');setNotice('');
  try{const response=await fetch(`${API}/retailers/${type}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:selected})});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.error||'Action failed.');await refresh();setNotice(`${data.changedIds.length} retailer(s) ${archived?'restored':'archived'}.`);}catch(e){setError(e.message);}finally{setBusy(false);}
 }
 if(editing!==undefined)return <RetailerSetup key={editing||'new'} initialRetailerId={editing} onBack={()=>{setEditing(undefined);refresh().catch(e=>setError(e.message));}}/>;
 return <div className="space-y-5" data-testid="client-management"><div className="flex flex-wrap justify-between gap-3"><div><h2 className="text-2xl font-bold">Client</h2><p className="text-sm text-slate-400 mt-2">Archive retains setup and history. Restore before editing or processing.</p></div><div className="flex gap-2"><button className={button} disabled={busy||!selected.length} onClick={archiveAction}>{archived?'Restore':'Archive'}{selected.length?` (${selected.length})`:''}</button><button className={button+' text-rose-300'} disabled={busy||!selected.length} onClick={remove}><Trash2 size={16}/>Delete{selected.length?` (${selected.length})`:''}</button><button className={button+' bg-cyan-600'} disabled={busy} onClick={()=>setEditing(null)}><Plus size={16}/>Add Retailer</button></div></div><label className="flex gap-2 text-sm"><input type="checkbox" checked={archived} disabled={busy} onChange={e=>{setArchived(e.target.checked);setSelected([]);}}/>Show Archived Retailers</label>{error&&<p role="alert" className="text-rose-300">{error}</p>}{notice&&<p role="status" className="text-emerald-300">{notice}</p>}<div className="rounded-xl bg-[var(--panel-background)] border border-slate-700 overflow-x-auto"><table className="w-full text-sm text-left"><thead className="bg-slate-900 text-slate-400"><tr><th className="p-3 w-12"><input ref={allBox} type="checkbox" aria-label="Select all retailers" disabled={busy||!visible.length} checked={visible.length>0&&selected.length===visible.length} onChange={e=>setSelected(e.target.checked?visible.map(r=>r.id):[])}/></th><th className="p-3">Retailer Name</th><th className="p-3">Setup Status</th><th className="p-3">Edit</th></tr></thead><tbody>{visible.map(r=><tr key={r.id} className="border-t border-slate-700"><td className="p-3"><input type="checkbox" aria-label={`Select ${r.name}`} checked={selected.includes(r.id)} disabled={busy} onChange={e=>setSelected(list=>e.target.checked?[...list,r.id]:list.filter(id=>id!==r.id))}/></td><td className="p-3 font-medium">{r.name}</td><td className="p-3"><span title="Readiness uses saved configuration and sample schema. Check the actual uploaded batch before starting." className={setupStatus(r)==='Ready for preprocessing'?'text-emerald-300':'text-amber-300'}>{setupStatus(r)}</span>{r.processingReadiness&&<details className="mt-2 text-xs text-slate-400 max-w-md"><summary className="cursor-pointer text-cyan-300">Readiness Details</summary><p className="mt-2">{r.processingReadiness.note}</p><ul className="space-y-1 mt-2">{r.processingReadiness.issues.map((issue,i)=><li className="text-rose-300" key={i}>{issue.sequence?`Rule ${issue.sequence}: `:''}{issue.message}</li>)}{r.processingReadiness.warnings.map((warning,i)=><li className="text-amber-300" key={i}>{warning}</li>)}</ul></details>}</td><td className="p-3"><button className={button} disabled={busy||r.archived} title={r.archived?'Restore before editing':'Edit retailer setup'} aria-label={`Edit ${r.name}`} onClick={()=>setEditing(r.id)}><Pencil size={16}/></button></td></tr>)}</tbody></table>{!visible.length&&<p className="p-6 text-center text-slate-400">No retailers in this view.</p>}</div></div>;
