import React,{useEffect,useState} from 'react';
const API=import.meta.env.VITE_API_URL||'/api/v1';
const input='w-full rounded border border-slate-600 bg-slate-950 p-2 text-sm';
const fields=[['rowsReceived','Rows Received'],['rowsAfterCleaning','Rows After Cleaning'],['storesReceived','Stores Received'],['storeTotalIncludingNew','Store Table + New Stores'],['newStores','New Stores'],['missingStores','Missing Stores'],['fileSizeBytes','File Size (bytes)'],['durationSeconds','Duration (seconds)']];
const value=(run,key)=>key==='durationSeconds'?run.durationSeconds:Array.isArray(run.metrics[key])?run.metrics[key].length:run.metrics[key];
