export default function CompareRuns({jobs,initialId,onClose}){
 const [left,setLeft]=useState(initialId),[right,setRight]=useState(''),[data,setData]=useState(null),[error,setError]=useState('');
 const selected=jobs.find(j=>j.id===left),options=jobs.filter(j=>j.retailer_id===selected?.retailer_id&&j.id!==left);
 useEffect(()=>{setRight(options[0]?.id||'');},[left]);
 useEffect(()=>{let live=true;setData(null);setError('');if(left&&right)fetch(`${API}/batches/compare?left=${encodeURIComponent(left)}&right=${encodeURIComponent(right)}`).then(async r=>{const d=await r.json();if(!r.ok||!d.success)throw new Error(d.error);if(live)setData(d);}).catch(e=>{if(live)setError(e.message);});return()=>{live=false;};},[left,right]);
 const label=j=>`${j.retailer_name} · ${j.period} · ${j.status} · ${j.id}`;
 return <div className="fixed inset-0 z-50 bg-slate-950/85 flex items-center justify-center p-4"><section role="dialog" aria-modal="true" aria-label="Compare runs" className="bg-slate-800 rounded-xl border border-slate-600 w-full max-w-5xl max-h-[90vh] overflow-auto p-5 space-y-4"><div className="flex justify-between"><h3 className="text-xl font-bold">Compare Runs</h3><button className="border rounded px-3 py-1" onClick={onClose}>Close</button></div><p className="text-sm text-slate-400">Compare two recorded runs of the same retailer. Change = comparison minus baseline. Cancelled and historical metrics may be unavailable.</p><div className="grid md:grid-cols-2 gap-3"><label>Baseline<select className={input} value={left} onChange={e=>setLeft(e.target.value)}>{jobs.map(j=><option key={j.id} value={j.id}>{label(j)}</option>)}</select></label><label>Comparison<select className={input} value={right} onChange={e=>setRight(e.target.value)}><option value="">Choose a second run</option>{options.map(j=><option key={j.id} value={j.id}>{label(j)}</option>)}</select></label></div>{!options.length&&<p className="text-amber-300">This retailer needs another recorded run to compare.</p>}{error&&<p role="alert" className="text-rose-300">{error}</p>}{data&&<><div className="overflow-auto"><table className="w-full text-left text-sm"><thead><tr>{['Metric','Baseline','Comparison','Change'].map(h=><th className="p-2" key={h}>{h}</th>)}</tr></thead><tbody>{fields.map(([key,label])=><tr className="border-t border-slate-600" key={key}><td className="p-2">{label}</td><td className="p-2">{format(value(data.left,key))}</td><td className="p-2">{format(value(data.right,key))}</td><td className="p-2 text-cyan-300">{data.deltas[key]>0?'+':''}{format(data.deltas[key])}</td></tr>)}</tbody></table></div><div className="grid md:grid-cols-2 gap-4">{[['Baseline',data.left],['Comparison',data.right]].map(([label,run])=><div key={label} className="border border-slate-600 rounded p-3 space-y-2 text-sm"><h4 className="font-bold">{label}: {run.status}</h4><p>{run.filename} · {run.period}</p><p>Configuration: {run.metrics.configurationVersion?`v${run.metrics.configurationVersion.version}`:'Not captured'}</p><p className="text-rose-300">{run.errorCodes.join(' · ')||'No errors recorded'}</p>{run.metrics.cancellationDetails&&<p>{run.metrics.cancellationDetails.reason}</p>}{run.metrics.failureDetails?.map(d=><p key={d.sequence}>Rule {d.sequence}: {d.ruleName} · {d.attempt}/{d.maxAttempts} failed attempts{d.recoveredOnAttempt?` · recovered at ${d.recoveredOnAttempt}`:''}<br/>{d.reason}</p>)}{['newStores','missingStores'].map(k=><p key={k}>{k==='newStores'?'New':'Missing'} Stores: {run.metrics[k]?.map(s=>s.key).join(', ')|| (run.metrics[k]==null?'Unavailable':'None')}</p>)}</div>)}</div><h4 className="font-bold">Rule Changes</h4>{data.ruleChanges.length?<ul className="text-sm space-y-2">{data.ruleChanges.map(r=><li key={r.ruleId}>{r.change}: {r.ruleName} · sequence {r.beforeSequence??'—'} → {r.afterSequence??'—'}</li>)}</ul>:<p className="text-sm text-slate-400">No saved rule changes between these runs.</p>}</>}</section></div>;
