 return <section className="rounded-xl border border-slate-700 bg-slate-800 p-5 space-y-4"><div className="flex justify-between"><h3 className="text-lg font-semibold">Input Files</h3><button className={button} disabled={busy||!!draft} onClick={()=>edit(null)}>Add Input File</button></div><p className="text-sm text-slate-400">Each Transaction or Master Product input has separate settings and a sample smaller than 1 MB. File Path can be a file or folder inside Codex; Filename accepts patterns such as sales_*.csv. ZIP inputs must contain exactly one file of the chosen type. Header Row is 1-based.</p><p className="text-xs text-slate-400">Automatic mode polls while this app is running, waits for two stable scans and processes new or changed files in the current Malaysia ISO week. Unchanged accepted content is skipped. Read From Path lets you choose an ISO week.</p>{error&&<p role="alert" className="text-rose-300">{error}</p>}{notice&&<p role="status" className="text-cyan-300">{notice}</p>}
