export default function KPIRecords(){
 const [records,setRecords]=useState([]),[filter,setFilter]=useState(''),[page,setPage]=useState(0),[chosen,setChosen]=useState(null),[checked,setChecked]=useState(false),[note,setNote]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 async function refresh(){const d=await api('/kpi-records');setRecords(d.records);return d.records;}
 useEffect(()=>{let live=true;const load=()=>api('/kpi-records').then(d=>{if(live)setRecords(d.records);}).catch(e=>{if(live)setError(e.message);});load();const timer=setInterval(load,10000);return()=>{live=false;clearInterval(timer);};},[]);
 const filtered=records.filter(r=>`${r.retailer_name} ${r.period} ${r.filename} ${r.status}`.toLowerCase().includes(filter.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/25));
