/tr>)}</tbody></table></div><details className="text-xs"><summary className="cursor-pointer">Baseline runs ({k.weeksUsed}/{k.settings.weeks})</summary>{k.baselineRuns.map(b=><p key={b.jobId} className="mt-2">{b.period} · {b.jobId}</p>)}{k.missingWeeks.length>0&&<p className="text-amber-300 mt-2">Unavailable: {k.missingWeeks.join(', ')}</p>}</details>{k.review?<div className="text-sm rounded border border-cyan-700 p-3"><p>Manually checked {time(k.review.checkedAt)}</p><p className="mt-2 whitespace-pre-wrap">{k.review.note}</p></div>:k.flagged&&chosen.status==='Completed with Interruption'&&<div className="space-y-3 border border-amber-700 rounded p-3"><label className="flex gap-2 text-sm"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/>I manually checked the totals, store deviations and baseline runs.</label><label className="block text-sm">Review Note<textarea className={input+' block w-full mt-2'} rows={3} maxLength={1000} value={note} onChange={e=>setNote(e.target.value)}/></label><button className={button+' text-cyan-300'} disabled={busy||!checked||!note.trim()} onClick={()=>action('kpi-review')}>Record Manual Check</button></div>}{['Completed','Completed with Interruption'].includes(chosen.status)&&<button className={button+' text-emerald-300'} disabled={busy||(k.flagged&&!k.review)} onClick={()=>action('approve')}>Approve Job</button>}{chosen.approvedAt&&<p className="text-cyan-300 text-sm">Approved {time(chosen.approvedAt)}</p>}</section></div>}
