 async function load(){const response=await fetch(`${API}/batches/${jobId}/stores/review`);const d=await response.json();if(!response.ok||!d.success)throw new Error(d.error||'Could not load New Stores.');setData(d);setRows(d.stores);setSelected([]);setDirty(false);}
