 const pending=rows.filter(s=>s.decision==='Pending review');
 return <section className="space-y-5" data-testid="new-store-review"><div className="flex flex-wrap justify-between gap-3"><div><h2 className="text-2xl font-bold">Review New Stores</h2><p className="mt-2 text-sm text-slate-400">{data?.retailerName} · {data?.period} · {jobId}</p></div><button className={button} disabled={busy} onClick={()=>{if(!dirty||window.confirm('Discard unsaved store review edits?'))onBack();}}>Back to Batch Log</button></div><p className="text-sm text-slate-400">Review each store’s name, address and status. Select stores to add, then approve them. Approve Job is a separate action. Unselected stores remain pending.</p>{error&&<p role="alert" className="text-rose-300">{error}</p>}{notice&&<p role="status" className="text-emerald-300">{notice}</p>}<div className="overflow-auto rounded-xl bg-slate-800 border border-slate-700"><table className="w-full text-sm text-left"><thead className="bg-slate-900 text-slate-400"><tr><th className="p-3"><input type="checkbox" aria-label="Select all pending stores" disabled={busy||!pending.length} checked={pending.length>0&&selected.length===pending.length} onChange={e=>setSelected(e.target.checked?pending.map(s=>s.key):[])}/></th>{['Store ID','Store Name','Store Address','Status','Exception','Review / SUITE Storecode'].map(h=><th className="p-3" key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(s=>{const editable=s.decision==='Pending review';return <tr className="border-t border-slate-700" key={s.key}><td className="p-3"><input aria-label={`Select store ${s.key}`} type="checkbox" disabled={busy||!editable} checked={selected.includes(s.key)} onChange={e=>setSelected(list=>e.target.checked?[...list,s.key]:list.filter(k=>k!==s.key))}/></td><td className="p-3 whitespace-nowrap">{s.key}</td><td className="p-3 min-w-48"><input aria-label={`Store name ${s.key}`} className={input} value={s.name} maxLength={120} disabled={busy||!editable} onChange={e=>edit(s.key,{name:e.target.value})}/></td><td className="p-3 min-w-56"><textarea aria-label={`Store address ${s.key}`} className={input} value={s.address||''} rows={2} maxLength={2000} disabled={busy||!editable} onChange={e=>edit(s.key,{address:e.target.value})}/></td><td className="p-3"><select aria-label={`Store status ${s.key}`} className={input} value={s.status||'Active'} disabled={busy||!editable} onChange={e=>edit(s.key,{status:e.target.value})}><option>Active</option><option>Inactive</option></select></td><td className="p-3"><select aria-label={`Store exception ${s.key}`} className={input} value={s.exception?'yes':'no'} disabled={busy||!editable} onChange={e=>edit(s.key,{exception:e.target.value==='yes'})}><option value="no">No</option><option value="yes">Yes</option></select></td><td className="p-3"><span className={editable?'text-amber-300':'text-emerald-300'}>{s.decision}</span><p className="mt-1 text-xs font-mono">{s.suiteCode||'Generated after approval'}</p></td></tr>;})}</tbody></table>{data&&!rows.length&&<p className="p-5 text-slate-400">No new stores were flagged for this run.</p>}</div><div className="flex justify-between items-center"><p className="text-sm text-slate-400">{pending.length} pending · {selected.length} selected</p><button className={button+' bg-cyan-600'} disabled={busy||!selected.length} onClick={approve}>{busy?'Approving…':'Approve New Stores'}</button></div></section>;
