                            record_delivery(rid,p['id'],'file:'+hashlib.sha256((str(path)+str(signature)).encode()).hexdigest(),'Blocked',str(exc))
        finally:poll_lock.release()
    app.extensions['input_poll_once']=poll_once
    def watch():
        while True:
            time.sleep(2)
            if app.testing:continue
