"""Input profile validation and bounded parsing, without exposing passwords."""
import csv,io,json,os,re,zipfile,ctypes,fnmatch
from pathlib import Path,PurePosixPath
from hashlib import sha256
DELIMITERS={'Comma':',','Tab':'\t','Semicolon':';','Pipe':'|','Caret':'^'}
ENCODINGS=['utf-8-sig','utf-8','utf-16','utf-16-le','utf-16-be','cp1252','latin-1','ascii']
TYPES=['CSV','TSV','Text','Excel (.xlsx)','JSON']
EXTENSIONS={'CSV':'.csv','TSV':'.tsv','Text':'.txt','Excel (.xlsx)':'.xlsx','JSON':'.json'}
LIMIT=50*1024*1024
def validate_profiles(profiles):
    if not isinstance(profiles,list) or len(profiles)>50:raise ValueError('Use at most 50 input files.')
    from kpi_records import validate_kpi
    result=[];seen=set()
    for p in profiles:
        if not isinstance(p,dict):raise ValueError('Invalid input file settings.')
        pid=p.get('id')
        if not isinstance(pid,str) or not re.fullmatch(r'INPUT-[a-zA-Z0-9-]{1,64}',pid) or pid in seen:raise ValueError('Input files need distinct valid IDs.')
        seen.add(pid)
        for key,values in [('delimiter',DELIMITERS),('encoding',ENCODINGS),('fileType',TYPES),('purpose',['Transaction','Master Product']),('readMode',['Manual','Automatic'])]:
            if p.get(key) not in values:raise ValueError(f'Choose a valid {key}.')
        modern=p.get('settingsVersion')==2
        for key in ['filename','filePath']:
            if not isinstance(p.get(key),str) or (not p[key].strip() and (key=='filename' or modern or p.get('readMode')=='Automatic')) or len(p[key])>(200 if key=='filename' else 1000):raise ValueError(f'{key} is required and must fit the length limit.')
        if any(c in p['filename'] for c in ['/', '\\', ':']) or p['filename'] in ['.','..']:raise ValueError('Filename must be a name or wildcard pattern, without a path.')
        if not isinstance(p.get('isZipFolder'),bool):raise ValueError('Choose whether the input is a ZIP archive.')
        for key,maximum in [('maxColumns',1000),('headerRow',10000)]:
            if isinstance(p.get(key),bool) or not isinstance(p.get(key),int) or not 1<=p[key]<=maximum:raise ValueError(f'{key} must be a whole number from 1 to {maximum}.')
        if p.get('watchInterval',60) not in [60,300,900]:raise ValueError('Choose a watch interval of 1, 5 or 15 minutes.')
        zipname=p.get('zipFolderName','')
        if not isinstance(zipname,str) or len(zipname)>200 or any(c in zipname for c in ['/', '\\', ':']):raise ValueError('Zip Folder Name must be a filename or pattern, without a path.')
        if modern and p['isZipFolder'] and (not zipname.strip() or not zipname.lower().endswith('.zip')):raise ValueError('Zip Folder Name is required and must end in .zip.')
        revision=p.get('passwordRevision',0)
        if isinstance(revision,bool) or not isinstance(revision,int) or not 0<=revision<=2147483647:raise ValueError('Invalid password revision.')
        if p['fileType']=='JSON' and p['headerRow']!=1:raise ValueError('JSON has named keys; Header Row must be 1.')
        result.append({k:p[k] for k in ['id','delimiter','encoding','fileType','purpose','filename','filePath','isZipFolder','maxColumns','headerRow','readMode']} | {'watchInterval':p.get('watchInterval',60),'passwordRevision':int(p.get('passwordRevision',0)), 'kpi':validate_kpi(p.get('kpi')), 'settingsVersion':p.get('settingsVersion',1), 'zipFolderName':zipname, 'hasSheetPassword':bool(p.get('hasSheetPassword',False))})
    return result

def parse_hash(profile):
    values={k:profile.get(k) for k in ['delimiter','encoding','fileType','isZipFolder','maxColumns','headerRow','passwordRevision']}
    if profile.get('settingsVersion')==2 and profile['isZipFolder']:values['innerFilename']=profile['filename']
    return sha256(json.dumps(values,sort_keys=True).encode()).hexdigest()

def protect_password(text):
    if os.name!='nt':raise ValueError('Password storage requires Windows user encryption.')
    from ctypes import wintypes
    class Blob(ctypes.Structure):_fields_=[('cbData',wintypes.DWORD),('pbData',ctypes.POINTER(ctypes.c_ubyte))]
    source=text.encode();buffer=ctypes.create_string_buffer(source);a=Blob(len(source),ctypes.cast(buffer,ctypes.POINTER(ctypes.c_ubyte)));b=Blob()
    if not ctypes.windll.crypt32.CryptProtectData(ctypes.byref(a),None,None,None,None,1,ctypes.byref(b)):raise ValueError('Unable to securely save the sheet password.')
    try:return ctypes.string_at(b.pbData,b.cbData)
    finally:ctypes.windll.kernel32.LocalFree(b.pbData)

def reveal_password(protected):
    if not protected:return ''
    from ctypes import wintypes
    class Blob(ctypes.Structure):_fields_=[('cbData',wintypes.DWORD),('pbData',ctypes.POINTER(ctypes.c_ubyte))]
    buffer=ctypes.create_string_buffer(protected);a=Blob(len(protected),ctypes.cast(buffer,ctypes.POINTER(ctypes.c_ubyte)));b=Blob()
    if not ctypes.windll.crypt32.CryptUnprotectData(ctypes.byref(a),None,None,None,None,1,ctypes.byref(b)):raise ValueError('Unable to decrypt the saved sheet password under this Windows user.')
    try:return ctypes.string_at(b.pbData,b.cbData).decode()
    finally:ctypes.windll.kernel32.LocalFree(b.pbData)

def read_records(source,filename,p,password='',limit=LIMIT):
    if len(source)>limit:raise ValueError('Input exceeds the file size limit.')
    extension=EXTENSIONS[p['fileType']]
    if p['isZipFolder']:
        try:
            with zipfile.ZipFile(io.BytesIO(source)) as z:
                members=z.infolist()
                if len(members)>100:raise ValueError('ZIP supports at most 100 entries.')
                for member in members:
                    name=member.filename.replace('\\','/');parts=PurePosixPath(name)
                    if parts.is_absolute() or '..' in parts.parts or ':' in name:raise ValueError('ZIP contains an unsafe entry name.')
                selected=[m for m in members if not m.is_dir() and m.filename.lower().endswith(extension) and (p.get('settingsVersion')!=2 or fnmatch.fnmatchcase(PurePosixPath(m.filename.replace('\\','/')).name,p['filename']))]
                if len(selected)!=1:raise ValueError('ZIP must contain exactly one matching Filename of the configured type.')
                member=selected[0]
                if member.flag_bits&1:raise ValueError('Password-protected ZIP archives are not supported; Sheet Password is for Excel.')
                if member.file_size>limit:raise ValueError('Uncompressed ZIP input exceeds the file size limit.')
                with z.open(member) as f:source=f.read(limit+1)
                if len(source)>limit:raise ValueError('Uncompressed ZIP input exceeds the file size limit.')
        except zipfile.BadZipFile:raise ValueError('Input is not a valid ZIP archive.')
        except (NotImplementedError,RuntimeError):raise ValueError('ZIP compression or protection is unsupported.')
    elif not filename.lower().endswith(extension):raise ValueError('Sample or input file must match the configured file type.')
    maxcols=p['maxColumns'];header=p['headerRow']
    if p['fileType']=='JSON':
        try:records=json.loads(source.decode(p['encoding']))
        except (UnicodeError,json.JSONDecodeError):raise ValueError('JSON cannot be read with the chosen encoding or structure.')
        records=[records] if isinstance(records,dict) else records
    else:
        if p['fileType']=='Excel (.xlsx)':
            import msoffcrypto
            try:
                office=msoffcrypto.OfficeFile(io.BytesIO(source))
                if office.is_encrypted():
                    if not password:raise ValueError('This Excel workbook requires a Sheet Password.')
                    output=io.BytesIO();office.load_key(password=password);office.decrypt(output);source=output.getvalue()
            except ValueError:raise
            except Exception:raise ValueError('Excel could not be opened. Check the workbook and Sheet Password.')
            from openpyxl import load_workbook
            try:workbook=load_workbook(io.BytesIO(source),read_only=True,data_only=True)
            except Exception:raise ValueError('Excel workbook could not be read.')
            try:
                sheet=workbook.worksheets[0]
                if sheet.max_column and sheet.max_column>maxcols:raise ValueError('Excel input exceeds Max Columns.')
                rows=sheet.iter_rows(values_only=True)
                records=tabular_records(rows,header,maxcols)
            finally:workbook.close()
        else:
            try:text=source.decode(p['encoding'])
            except UnicodeError:raise ValueError('Input cannot be decoded with the chosen encoding.')
            try:records=tabular_records(csv.reader(io.StringIO(text,newline=''),delimiter=DELIMITERS[p['delimiter']],strict=True),header,maxcols)
            except csv.Error:raise ValueError('Delimited input is malformed; check delimiter and quoting.')
    if not isinstance(records,list) or not records or not all(isinstance(r,dict) for r in records):raise ValueError('Input must contain at least one data row.')
    columns=set(k for r in records for k in r)
    if any(not isinstance(k,str) or not k.strip() for k in columns):raise ValueError('Headers or JSON keys must be nonempty text.')
    if len(columns)>maxcols:raise ValueError('Input exceeds Max Columns.')
    return records

def tabular_records(rows,header,maxcols):
    iterator=iter(rows)
    for _ in range(header-1):
        if next(iterator,None) is None:raise ValueError('Header Row is beyond the end of the input.')
    raw=next(iterator,None)
    if raw is None:raise ValueError('Header Row is beyond the end of the input.')
    headers=[str(v).strip() if v is not None else '' for v in raw]
    if not headers or len(headers)>maxcols:raise ValueError('Header exceeds Max Columns or is empty.')
    if any(not h for h in headers) or len(set(headers))!=len(headers):raise ValueError('Headers must be nonempty and unique.')
    records=[]
    for row in iterator:
        if not any(v is not None and str(v)!='' for v in row):continue
        if len(row)>maxcols or len(row)>len(headers):raise ValueError('A row has more columns than the header or Max Columns.')
        values=[v.isoformat() if hasattr(v,'isoformat') else str(v) if v is not None else '' for v in row]
        records.append(dict(zip(headers,values+['']*(len(headers)-len(values)))))
    return records

"""Snapshot weekly KPI comparisons and explicit operator review."""
import json,math
from datetime import datetime,timedelta
from decimal import Decimal,DecimalException
from flask import request,jsonify
from database import get_db_connection
DEFAULTS={'weeks':8,'storeLimit':30,'retailerLimit':30,'countLimit':40,'salesField':'','quantityField':'','storeField':''}
def validate_kpi(value):
    if value is None:value={}
    if not isinstance(value,dict):raise ValueError('Invalid KPI settings.')
    result=DEFAULTS|value
    if isinstance(result['weeks'],bool) or not isinstance(result['weeks'],int) or not 1<=result['weeks']<=52:raise ValueError('KPI weeks must be from 1 to 52.')
    for key in ['storeLimit','retailerLimit','countLimit']:
        if isinstance(result[key],bool) or not isinstance(result[key],(int,float)) or not math.isfinite(result[key]) or not 0<=result[key]<=1000:raise ValueError('KPI ranges must be finite percentages from 0 to 1000.')
    for key in ['salesField','quantityField','storeField']:
        if not isinstance(result[key],str) or len(result[key])>200:raise ValueError('Select valid KPI fields.')
        result[key]=result[key].strip()
    return {key:result[key] for key in DEFAULTS}
def totals(records,settings):
    sales=Decimal(0);quantity=Decimal(0);stores={};issues=[]
    missing=[key for key in ['salesField','quantityField','storeField'] if not settings[key]]
    if missing:return {'sales':None,'quantity':None,'rows':len(records),'stores':{},'issues':['Select Sales, Quantity and Store ID fields in Transaction input settings.']}
    invalid=0
    for row in records:
        try:
            amount=Decimal(str(row[settings['salesField']]).strip());units=Decimal(str(row[settings['quantityField']]).strip())
            store=str(row[settings['storeField']]).strip() if row[settings['storeField']] is not None else ''
            if not amount.is_finite() or not units.is_finite() or not store:raise ValueError()
            key=store.casefold();next_sales=sales+amount;next_quantity=quantity+units
            next_store=stores.get(key,{}).get('sales',Decimal(0))+amount
        except (KeyError,DecimalException,ValueError,TypeError):invalid+=1;continue
        sales=next_sales;quantity=next_quantity
        if key not in stores:stores[key]={'storeId':store,'sales':Decimal(0)}
        stores[key]['sales']=next_store
    if invalid:issues.append(f'{invalid} rows have missing or invalid KPI fields. Totals are unavailable until these are corrected.')
    try:
        numeric=[float(sales),float(quantity),*[float(s['sales']) for s in stores.values()]]
        if not all(math.isfinite(v) for v in numeric):raise ValueError()
    except (OverflowError,ValueError):issues.append('KPI totals exceed the supported numeric range.')
    if issues:return {'sales':None,'quantity':None,'rows':len(records),'stores':{},'issues':issues}
    return {'sales':float(sales),'quantity':float(quantity),'rows':len(records),
        'stores':{key:{'storeId':s['storeId'],'sales':float(s['sales'])} for key,s in stores.items()},'issues':[]}
def change(current,baseline):
    if current is None or baseline is None:return None
    if baseline==0:return 0.0 if current==0 else None
    result=float((Decimal(str(current))-Decimal(str(baseline)))/abs(Decimal(str(baseline)))*100)
    return result if math.isfinite(result) else None

def average(values):
    return float(sum((Decimal(str(v)) for v in values),Decimal(0))/len(values)) if values else None
def evaluate_kpi(db,rid,period,records,profile):
    if not profile or profile.get('purpose')!='Transaction':return None
    settings=validate_kpi(profile.get('kpi'));current=totals(records,settings)
    year,week=period.split('-W');start=datetime.fromisocalendar(int(year),int(week),1)
    periods=[(start-timedelta(weeks=i)).isocalendar() for i in range(1,settings['weeks']+1)]
    periods=[f'{p.year:04d}-W{p.week:02d}' for p in periods]
    history=[];missing=[]
    for prior in periods:
        candidates=db.execute("SELECT id,output FROM batch_jobs WHERE retailer_id=? AND period=? AND status IN ('Completed','Approved Job') AND json_extract(metrics,'$.inputFile.id')=? ORDER BY start_time DESC,rowid DESC",(rid,prior,profile['id'])).fetchall()
        chosen=None
        for row in candidates:
            if not row['output']:continue
            aggregate=totals(json.loads(row['output']),settings)
            if not aggregate['issues']:chosen={'jobId':row['id'],'period':prior,**aggregate};break
        if chosen:history.append(chosen)
        else:missing.append(prior)
    n=len(history);mean=lambda key:average([h[key] for h in history])
    retailer_base=mean('sales');count_base=mean('rows')
    retailer_percent=change(current['sales'],retailer_base);count_percent=change(current['rows'],count_base)
    flags=list(current['issues']);stores=[]
    if not n:flags.append('No eligible previous-week baseline. Check this first KPI run manually.')
    if not current['issues'] and n:
        keys=set(current['stores'])|{key for h in history for key in h['stores']}
        for key in sorted(keys):
            previous=[h['stores'].get(key,{}).get('sales',0) for h in history]
            baseline=average(previous);present=current['stores'].get(key)
            store_id=(present or next(h['stores'][key] for h in history if key in h['stores']))['storeId']
            amount=present['sales'] if present else 0;percent=change(amount,baseline)
            flagged=percent is None or abs(percent)>settings['storeLimit']
            reason='Nonzero sales against a zero store baseline.' if percent is None else 'Outside allowed store range.' if flagged else ''
            stores.append({'storeId':store_id,'sales':amount,'baselineSales':baseline,'percent':percent,'flagged':flagged,'reason':reason})
        if any(s['flagged'] for s in stores):flags.append('One or more stores are outside the allowed sales range or have a zero baseline.')
        if retailer_percent is None:flags.append('Retailer sales percentage is unavailable against a zero baseline.')
        elif abs(retailer_percent)>settings['retailerLimit']:flags.append('Retailer sales are outside the allowed range.')
        if count_percent is None:flags.append('Row-count percentage is unavailable against a zero baseline.')
        elif abs(count_percent)>settings['countLimit']:flags.append('Rows Count is outside the allowed range.')
    available=[s['percent'] for s in stores if s['percent'] is not None]
    return {'settings':settings,'sales':current['sales'],'quantity':current['quantity'],'rowsCount':current['rows'],
        'storePercent':average(available) if available and len(available)==len(stores) else None,
        'retailerPercent':retailer_percent,'countPercent':count_percent,'baselineSales':retailer_base,'baselineRows':count_base,
        'weeksUsed':n,'missingWeeks':missing,'baselineRuns':[{'jobId':h['jobId'],'period':h['period']} for h in history],
        'stores':stores,'flagged':bool(flags),'flags':flags,'review':None}
def public_record(row):
    metrics=json.loads(row['metrics'] or '{}')
    return {k:row[k] for k in ['id','retailer_id','retailer_name','period','filename','status','start_time']} | {
        'inputFile':metrics.get('inputFile'),'kpi':metrics.get('kpi'),'approvedAt':metrics.get('approvedAt')}
def register_kpi_routes(app,error):
    @app.route('/api/v1/kpi-records')
    def records():
        with get_db_connection() as db:
            rows=[public_record(r) for r in db.execute("SELECT * FROM batch_jobs WHERE json_extract(metrics,'$.inputFile.purpose')='Transaction' ORDER BY start_time DESC,rowid DESC")]
        return jsonify(success=True,records=rows)
    @app.route('/api/v1/batches/<jid>/kpi-review',methods=['POST'])
    def review(jid):
        body=request.get_json(silent=True)
        if not isinstance(body,dict) or body.get('checked') is not True or not isinstance(body.get('note'),str) or not body['note'].strip() or len(body['note'])>1000:return error('Confirm the manual check and enter a review note (up to 1,000 characters).')
        with get_db_connection() as db:
            db.execute('BEGIN IMMEDIATE');job=db.execute('SELECT * FROM batch_jobs WHERE id=?',(jid,)).fetchone()
            if not job:return error('Job not found.',404)
            metrics=json.loads(job['metrics'] or '{}');kpi=metrics.get('kpi')
            if job['status'] not in ['Completed','Completed with Interruption'] or not kpi or not kpi['flagged']:return error('Only a completed, flagged KPI run can be reviewed.',409)
            if kpi.get('review'):return error('KPI review is already recorded.',409)
            from batch_jobs import now
            stamp=now();kpi['review']={'checkedAt':stamp,'note':body['note'].strip()}
            audit=json.loads(job['audit'] or '[]');audit.append({'sequence':None,'ruleName':'Manual KPI review','category':'Action','attempt':1,'startTime':stamp,'endTime':stamp,'durationMs':0,'result':'Successful','errorCode':None,'message':body['note'].strip()})
            db.execute('UPDATE batch_jobs SET metrics=?,audit=? WHERE id=?',(json.dumps(metrics),json.dumps(audit),jid))
        return jsonify(success=True,review=kpi['review'])

from input_files import profile_parser
from retailer_archive import archive_state
"""Read-only schema/configuration checks before creating a batch run."""
import hashlib,io,json,re
from datetime import datetime,timezone
from werkzeug.datastructures import FileStorage
from flask import request,jsonify
from database import get_db_connection
from retailer_setup import validate_pipeline

def configuration_hash(config):
    return hashlib.sha256(json.dumps(config,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode('utf-8')).hexdigest()

def parse_source(source,filename,parser):
    file=FileStorage(stream=io.BytesIO(source),filename=filename)
    try:return parser(file)[0]
    finally:file.close()

def check_configuration(config,records,period,filename,source,store_field=''):
    issues=[];warnings=[];columns=set(k for row in records or [] for k in row)
    def issue(code,message,sequence=None,rule=None):issues.append(dict(code=code,message=message,sequence=sequence,ruleName=(rule or {}).get('name',''),field=(rule or {}).get('field','')))
    try:
        year,week=period.split('-W');datetime.fromisocalendar(int(year),int(week),1)
        if period!=f'{int(year):04d}-W{int(week):02d}':raise ValueError()
    except (ValueError,AttributeError,TypeError):issue('INVALID_PERIOD','Choose a valid ISO week in YYYY-Www format.')
    if not isinstance(store_field,str) or len(store_field)>200:issue('INVALID_STORE_FIELD','Store ID field must be text of at most 200 characters.')
    elif store_field.strip() and store_field.strip() not in columns:issue('STORE_FIELD_MISSING',f'Store ID field "{store_field.strip()}" is not in the file.')
    if not config:issue('RETAILER_MISSING','Choose an existing saved retailer setup.')
    else:
        if config.get('archived'):issue('RETAILER_ARCHIVED','Restore this retailer before processing.')
        pipeline=config.get('pipeline',[])
        if not isinstance(pipeline,list):issue('INVALID_PIPELINE','Saved rules must be a list.');pipeline=[]
        if len(pipeline)>100:issue('INVALID_PIPELINE','Use at most 100 rules.')
        seen=set()
        for sequence,rule in enumerate(pipeline,1):
            if not isinstance(rule,dict):issue('INVALID_RULE','Rule is not a valid configuration.',sequence);continue
            if isinstance(rule.get('id'),str):
                if rule['id'] in seen:issue('DUPLICATE_RULE_ID','Each rule needs a unique ID.',sequence,rule)
                seen.add(rule['id'])
            try:validate_pipeline([rule])
            except (ValueError,TypeError) as exc:issue('REFERENCE_ONLY' if rule.get('operation')=='reference' else 'INVALID_RULE',str(exc),sequence,rule);continue
            if rule.get('operation') in ['join','kpi'] or rule.get('inputFileId') or rule.get('stage')=='Layout':continue
            field=rule['field'];condition=rule.get('condition')
            if field not in columns:issue('RULE_FIELD_MISSING',f'Field "{field}" is unavailable at this sequence. Select an existing field or move its rename rule earlier.',sequence,rule)
            if condition and condition['field'] not in columns:issue('CONDITION_FIELD_MISSING',f'Condition field "{condition["field"]}" is unavailable at this sequence.',sequence,rule)
            if rule['operation']=='date':
                fmt=rule['dateFormat'];tokens=re.findall(r'%(.|$)',fmt)
                if any(token not in 'aAbBcdHIjmMpSUwWxXyYfzZGgVu%' for token in tokens):issue('INVALID_DATE_FORMAT','Source date format has an unsupported or incomplete directive. Example: %d/%m/%Y.',sequence,rule)
                else:
                    try:datetime.strptime('',fmt)
                    except re.error:issue('INVALID_DATE_FORMAT','Date format repeats a directive or has an invalid pattern.',sequence,rule)
                    except ValueError as exc:
                        if any(text in str(exc) for text in ['must be used with','incompatible with','bad directive','stray %']):issue('INVALID_DATE_FORMAT',str(exc),sequence,rule)
            if rule['operation']=='rename' and field in columns:
                target=rule['target']
                if target!=field and target in columns:issue('RENAME_TARGET_EXISTS',f'Rename target "{target}" already exists.',sequence,rule)
                else:
                    if not condition:columns.discard(field)
                    else:warnings.append(f'Rule {sequence}: a conditional rename may leave some rows without "{target}". Review the sample preview.')
                    columns.add(target)
        if not pipeline:warnings.append('No rules configured. This job will only parse and record the input.')
        if not config.get('stores'):warnings.append('No registered stores. Received stores will be flagged as new when Store IDs are available.')
    if not store_field:
        candidates=[c for c in set(k for row in records or [] for k in row) if re.sub(r'[^a-z0-9]','',c.lower()) in {'storeid','retailerstoreid','storecode','retailerstorecode','storekey'}]
        if len(candidates)!=1:warnings.append('Store ID field cannot be detected uniquely. Store counts and New/Missing Store flags may be unavailable; enter an override if needed.')
    return dict(ready=not issues,checkedAt=datetime.now(timezone.utc).isoformat(),configurationHash=configuration_hash(config) if config else None,
                retailerName=(config or {}).get('name',''),period=period,filename=filename,fileSizeBytes=len(source),fileSha256=hashlib.sha256(source).hexdigest(),rowsReceived=len(records or []),
                columns=sorted(set(k for row in records or [] for k in row)),issues=issues,warnings=warnings)

def preprocessing_report(config,source,filename,period,store_field,parser):
    try:records=parse_source(source,filename,parser)
    except Exception:
        report=check_configuration(config,[],period,filename,source,store_field)
        report['issues'].insert(0,dict(code='INPUT_PARSE_ERROR',message='File cannot be parsed. Supply a nonempty CSV, XLSX or JSON file with valid headers.',sequence=None,ruleName='',field=''))
        report['ready']=False
        return report
    return check_configuration(config,records,period,filename,source,store_field)

def extend_workflow_report(report,config,rid,pid,source,filename,parser):
    if not config or not (config.get('workflowVersion')==1 or any(r.get('operation') in ['join','kpi'] for r in config.get('pipeline',[]))):return report
    try:
        if not pid:raise ValueError('Select the saved primary Input File Settings.')
        if any(r.get('operation')=='join' for r in config.get('pipeline',[])) and config.get('primaryInputId') and pid!=config['primaryInputId']:raise ValueError('Select the configured primary input for linked processing.')
        from file_workflow import launch_state,schema_issues
        state,linked=launch_state(rid,config,pid,parse_source(source,filename,parser))
        report['linkedInputs']=linked;report['issues'].extend(schema_issues(state,config))
    except (ValueError,OSError,KeyError) as exc:report['issues'].append({'code':'LINKED_INPUT_ERROR','message':str(exc),'sequence':None,'ruleName':'Link Files','field':''})
    report['ready']=not report['issues'];return report

def register_preprocessing_routes(app,parser,error):
    @app.route('/api/v1/batches/preprocessing',methods=['POST'])
    def preprocessing_upload():
        file=request.files.get('file')
        if not file or not file.filename:return error('Select a data file to check.')
        rid=request.form.get('retailerId','')
        with get_db_connection() as db:
            row=db.execute('SELECT payload FROM retailer_configs WHERE id=?',(rid,)).fetchone()
            config=json.loads(row['payload']) if row else None
            if config is not None and archive_state(db,rid)['archived']:config['archived']=True
        selected_parser=parser
        if request.form.get('inputFileId'):
            try:selected_parser=profile_parser(rid,request.form['inputFileId'])
            except ValueError as exc:return error(str(exc))
        source=file.read();pid=request.form.get('inputFileId')
        report=preprocessing_report(config,source,file.filename,request.form.get('period',''),request.form.get('storeIdField',''),selected_parser)
        if config and (config.get('workflowVersion')==1 or any(r.get('operation') in ['join','kpi'] for r in config.get('pipeline',[]))):
            try:
                if not pid:raise ValueError('Select the saved primary Input File Settings.')
                if any(r.get('operation')=='join' for r in config.get('pipeline',[])) and config.get('primaryInputId') and pid!=config['primaryInputId']:raise ValueError('Select the configured primary input for linked processing.')
                from file_workflow import launch_state,schema_issues
                state,linked=launch_state(rid,config,pid,parse_source(source,file.filename,selected_parser))
                report['linkedInputs']=linked;report['issues'].extend(schema_issues(state,config))
            except (ValueError,OSError,KeyError) as exc:report['issues'].append({'code':'LINKED_INPUT_ERROR','message':str(exc),'sequence':None,'ruleName':'Link Files','field':''})
            report['ready']=not report['issues']
        return jsonify(success=True,report=report)

    @app.route('/api/v1/batches/<jid>/preprocessing',methods=['POST'])
    def preprocessing_reprocess(jid):
        body=request.get_json(silent=True)
        if body is None:body={}
        if not isinstance(body,dict):return error('Invalid preprocessing request.')
        with get_db_connection() as db:
            job=db.execute('SELECT * FROM batch_jobs WHERE id=?',(jid,)).fetchone()
            if not job:return error('Job not found.',404)
            row=db.execute('SELECT payload FROM retailer_configs WHERE id=?',(job['retailer_id'],)).fetchone()
            config=json.loads(row['payload']) if row else None
            if config is not None and archive_state(db,job['retailer_id'])['archived']:config['archived']=True
        selected_parser=parser
        pid=json.loads(job['metrics'] or '{}').get('inputFile',{}).get('id')
        if pid:
            try:selected_parser=profile_parser(job['retailer_id'],pid)
            except ValueError as exc:return error(str(exc))
        report=preprocessing_report(config,job['source'],job['filename'],body.get('period',job['period']),json.loads(job['metrics'] or '{}').get('storeIdField',''),selected_parser)
        extend_workflow_report(report,config,job['retailer_id'],pid,job['source'],job['filename'],selected_parser)
        return jsonify(success=True,report=report)

"""Configuration/sample readiness, independent of mandatory component labels."""
import copy,json
from retailer_setup import validate_retailer,validate_pipeline
from preprocessing import check_configuration

def readiness(db,rid,config):
    issues=[];warnings=[]
    note='Checks saved setup and sample fields only. The actual batch still needs preprocessing; valid sample values do not guarantee a successful job.'
    if config.get('archived'):
        return {'status':'Archived','ready':False,'issues':[{'message':'Restore this retailer before editing or processing.'}],'warnings':[], 'note':note}
    try:validate_retailer(copy.deepcopy(config))
    except (ValueError,TypeError,KeyError) as exc:issues.append({'code':'INVALID_SETUP','message':str(exc)})
    try:validate_pipeline(config.get('pipeline',[]))
    except (ValueError,TypeError,KeyError) as exc:issues.append({'code':'INVALID_RULES','message':str(exc)})
    profiles=config.get('inputFiles',[])
    if profiles:
        from input_file_io import parse_hash
        missing=False
        for profile in profiles:
            sample=db.execute('SELECT * FROM input_file_samples WHERE retailer_id=? AND input_id=?',(rid,profile['id'])).fetchone()
            label=f"{profile['purpose']} ({profile['filename']})"
            kpi_rule=next((r for r in config.get('pipeline',[]) if r.get('operation')=='kpi' and (not r.get('inputFileId') or r['inputFileId']==profile['id'])),None)
            if profile['purpose']=='Transaction' and kpi_rule and any(not kpi_rule.get('kpi',{}).get(key) for key in ['salesField','quantityField','storeField']):
                warnings.append(label+': select KPI Sales, Quantity and Store ID fields; otherwise the completed run requires manual review.')
            if not sample or sample['settings_hash']!=parse_hash(profile):
                missing=True;warnings.append(label+': upload a sample matching the current input settings.');continue
            if config.get('primaryInputId') and profile['id']!=config['primaryInputId'] and (config.get('workflowVersion')==1 or any(r.get('operation')=='join' for r in config.get('pipeline',[]))):continue
            report=check_configuration(config,json.loads(sample['records']),'2026-W01',sample['filename'],b'')
            issues.extend({**issue,'message':label+': '+issue['message']} for issue in report['issues'])
            warnings.extend(label+': '+warning for warning in report['warnings'])
        if not missing and (config.get('workflowVersion')==1 or any(r.get('operation')=='join' for r in config.get('pipeline',[]))):
            try:
                from file_workflow import sample_state,schema_issues
                primary=config.get('primaryInputId') or profiles[0]['id']
                issues.extend(schema_issues(sample_state(db,rid,config,primary),config))
            except (ValueError,KeyError) as exc:issues.append({'code':'WORKFLOW_SCHEMA_ERROR','message':str(exc)})
        return {'status':'Needs attention' if issues else 'Needs sample check' if missing else 'Ready for preprocessing',
            'ready':not issues and not missing,'issues':issues,'warnings':warnings,'note':note}
    sample=db.execute('SELECT filename,records FROM retailer_samples WHERE retailer_id=?',(rid,)).fetchone()
    if not issues and sample:
        records=json.loads(sample['records'])
        report=check_configuration(config,records,'2026-W01',sample['filename'],b'')
        issues.extend(report['issues']);warnings.extend(report['warnings'])
    elif not sample:
        warnings.append('Upload a sample to check rule fields and rename sequence, or check the actual batch in Data Streams.')
        if not config.get('pipeline'):warnings.append('No rules configured: processing will parse and record the input only.')
        if not config.get('stores'):warnings.append('No registered stores: received Store IDs will be flagged as new when available.')
    status='Needs attention' if issues else 'Ready for preprocessing' if sample else 'Needs sample check'
    return {'status':status,'ready':not issues and bool(sample),'issues':issues,'warnings':warnings,'note':note}

"""Archive state is separate from setup; keys, store codes and history survive."""
